class Solution:
    def ndcgAtK(self, ranked: List[float], ideal: List[float], k: int) -> float:
        def dcg(rels: List[float]) -> float:
            total = 0.0
            for i, rel in enumerate(rels[:k]):
                total += rel / math.log2(i + 2)
            return total
        idcg = dcg(sorted(ideal, reverse=True))
        if idcg == 0:
            return 0.0
        return dcg(ranked) / idcg

